# * Console tee logger -----------------------------------------------------------
class _TeeStdout:
    """* Tee stdout into a file for persistent logs.

    * Writes the same content to the original stdout and to the log file.
    * Replaces carriage returns in the log stream to keep lines readable.
    """

    def __init__(self, real_stdout: Any, log_file_handle: Any) -> None:
        self._real = real_stdout
        self._log = log_file_handle

    def write(self, s: str) -> int:
        try:
            self._real.write(s)
        except Exception:
            pass
        try:
            self._log.write(s.replace("\r", ""))
        except Exception:
            pass
        return len(s)

    def flush(self) -> None:
        try:
            self._real.flush()
        except Exception:
            pass
        try:
            self._log.flush()
        except Exception:
            pass

    def isatty(self) -> bool:
        try:
            return bool(self._real.isatty())
        except Exception:
            return False


# * Data models ------------------------------------------------------------------
@dataclass(frozen=True)
class VariantParams:
    codec: Literal["h264", "hevc"]
    quality: str  # NVENC CQ (e.g., "26", "30", "34", "40")
    b_frames: int
    temporal_aq: bool
    rc_lookahead: int
    aq_strength: int
    multipass: Literal["off", "qres", "fullres"]
    b_ref_mode: Literal[
        "disabled", "middle"
    ]  # NVENC only; ignored for software fallback
    main10: bool  # HEVC 10-bit main10 (HEVC only)
    label: str  # human-friendly name for report rows


# * Runtime state for async benchmark ------------------------------------------------
@dataclass
class BenchmarkState:
    inputs: list[Path]
    variants: list[VariantParams]
    out_reports: Path
    stats: ProcessingStats
    has_vmaf: bool
    require_vmaf: bool
    vmaf_model_dir: Path | None
    overwrite: bool
    concurrency: int
    keep_outputs: bool
    require_nvenc: bool

    sem: asyncio.Semaphore
    rows: list[dict[str, Any]]
    total_tasks: int
    processed_count: int
    start_ts: float
    stop_event: asyncio.Event

    variant_pending: dict[str, int]
    variant_start_ts: dict[str, float]
    variant_file_elapsed_sum: dict[str, float]
    variant_processed_count: dict[str, int]

    current_variant_slug: Optional[str]
    current_variant_cfg: str
    current_file_start_ts: Optional[float]


def _format_variant_cfg(var: VariantParams) -> str:
    """Render human-friendly current variant configuration string."""
    return (
        f"{var.codec} cq{var.quality} bf{var.b_frames} "
        f"br{var.b_ref_mode if var.codec=='hevc' else 'disabled'} "
        f"taq{int(var.temporal_aq)} la{var.rc_lookahead} aqs{var.aq_strength} mp{var.multipass}"
        f"{' 10bit' if (var.codec=='hevc' and var.main10) else ''}"
    )


async def heartbeat_loop(state: BenchmarkState) -> None:
    """Continuously render a single-line live status until stop_event is set."""
    last_len = 0
    while not state.stop_event.is_set():
        try:
            elapsed = max(0.0, time.perf_counter() - state.start_ts)
            done = state.processed_count
            total = state.total_tasks
            if done > 0:
                avg = elapsed / float(done)
                eta = avg * max(0, total - done)
            else:
                eta = 0.0
            var_done = sum(1 for v in state.variant_pending.values() if v == 0)
            var_total = len(state.variant_pending)
            epf = (
                (time.perf_counter() - state.current_file_start_ts)
                if state.current_file_start_ts
                else 0.0
            )
            epv = 0.0
            etav = 0.0
            if state.current_variant_slug:
                vslug = state.current_variant_slug
                vstart = state.variant_start_ts.get(vslug, state.start_ts)
                epv = max(0.0, time.perf_counter() - vstart)
                v_done_files = state.variant_processed_count.get(vslug, 0)
                v_total_files = len(state.inputs)
                v_elapsed_sum = state.variant_file_elapsed_sum.get(vslug, 0.0)
                v_avg = (v_elapsed_sum / v_done_files) if v_done_files > 0 else 0.0
                v_rem = max(0, v_total_files - v_done_files)
                etav = v_avg * v_rem
            line = (
                f" files {done}/{total} | vars {var_done}/{var_total} | {state.current_variant_cfg}"
                f" | EPF {epf:.1f}s | EPV {epv:.1f}s | EPB {elapsed:.1f}s | ETAv {format_duration(etav)} | ETA {format_duration(eta)}"
            )
            padded = line + (" " * max(0, last_len - len(line)))
            sys.stdout.write("\r" + padded)
            sys.stdout.flush()
            last_len = max(last_len, len(line))
        except Exception:
            pass
        await asyncio.sleep(0.5)
    try:
        sys.stdout.write("\r" + " " * last_len + "\r")
        sys.stdout.flush()
    except Exception:
        pass


async def process_one_task(
    state: BenchmarkState, inp: Path, var: VariantParams
) -> None:
    """Process a single (input,variant) pair: encode, metrics, report, cleanup."""
    async with state.sem:
        # Duration for RTF
        dur = await get_video_duration(str(inp))
        duration_s = float(dur) if dur is not None else 0.0
        # Input size
        try:
            size_in = inp.stat().st_size
        except Exception:
            size_in = 0
        # Start line
        typer.echo(
            f"-> Start: {inp.name} | {var.codec} cq{var.quality} bf{var.b_frames} "
            f"taq{int(var.temporal_aq)} la{var.rc_lookahead} aqs{var.aq_strength} mp{var.multipass}"
            f"{' main10' if (var.codec=='hevc' and var.main10) else ''}"
        )
        # Live status update
        vslug = _variant_slug(var)
        if vslug not in state.variant_start_ts:
            state.variant_start_ts[vslug] = time.perf_counter()
            state.variant_file_elapsed_sum[vslug] = 0.0
            state.variant_processed_count[vslug] = 0
        state.current_variant_slug = vslug
        state.current_variant_cfg = _format_variant_cfg(var)
        state.current_file_start_ts = time.perf_counter()

        # Encode
        out_file, used_nvenc, enc_elapsed = await _encode_once(
            inp,
            WIN_TEMP_ROOT,
            var,
            overwrite=state.overwrite,
            stats=state.stats,
            total_duration=duration_s if duration_s > 0 else None,
            require_nvenc=state.require_nvenc,
        )
        # Update accumulators
        try:
            state.variant_file_elapsed_sum[vslug] = (
                state.variant_file_elapsed_sum.get(vslug, 0.0) + enc_elapsed
            )
            state.variant_processed_count[vslug] = (
                state.variant_processed_count.get(vslug, 0) + 1
            )
        except Exception:
            pass

        note = "" if used_nvenc else "software_fallback"
        if out_file is None or not out_file.exists():
            state.rows.append(
                {
                    "input": str(inp),
                    "variant": _variant_slug(var),
                    "label": var.label,
                    "codec": var.codec,
                    "quality": var.quality,
                    "elapsed_s": round(enc_elapsed, 3),
                    "duration_s": round(duration_s, 3),
                    "rtf": round(
                        (duration_s / enc_elapsed) if enc_elapsed > 0 else 0.0, 3
                    ),
                    "size_in": size_in,
                    "size_out": 0,
                    "size_reduction_percent": 0.0,
                    "efficiency_ratio": 0.0,
                    "status": "failed",
                    "note": note,
                }
            )
            typer.echo(
                f"<- Fail:  {inp.name} | {var.codec} cq{var.quality} | elapsed {enc_elapsed:.1f}s"
            )
            state.processed_count += 1
            slug = _variant_slug(var)
            state.variant_pending[slug] -= 1
            if state.variant_pending[slug] == 0:
                typer.echo(f"<= Variant done:  {slug}")
            return

        # Output size
        try:
            size_out = out_file.stat().st_size
        except Exception:
            size_out = 0

        # Metrics
        metrics: dict[str, float] = {}
        if state.has_vmaf:
            metrics = await compute_metrics_vmaf(
                inp, out_file, model_dir=state.vmaf_model_dir
            )
            if state.require_vmaf and ("vmaf" not in metrics):
                state.rows.append(
                    {
                        "input": str(inp),
                        "variant": _variant_slug(var),
                        "label": var.label,
                        "codec": var.codec,
                        "quality": var.quality,
                        "elapsed_s": round(enc_elapsed, 3),
                        "duration_s": round(duration_s, 3),
                        "rtf": round(
                            (duration_s / enc_elapsed) if enc_elapsed > 0 else 0.0, 3
                        ),
                        "size_in": size_in,
                        "size_out": size_out,
                        "size_reduction_percent": 0.0,
                        "efficiency_ratio": 0.0,
                        "status": "failed-metric",
                        "note": "vmaf-required",
                    }
                )
                if not state.keep_outputs:
                    with contextlib.suppress(Exception):
                        out_file.unlink()
                return
        if not metrics:
            metrics = await compute_metrics_ssim_psnr(inp, out_file)

        qual_for_eff = metrics.get("vmaf")
        size_red, eff_ratio = _efficiency_metric(size_in, size_out, qual_for_eff)
        row: dict[str, Any] = {
            "input": str(inp),
            "variant": _variant_slug(var),
            "label": var.label,
            "codec": var.codec,
            "quality": var.quality,
            "b_frames": var.b_frames,
            "temporal_aq": int(var.temporal_aq),
            "rc_lookahead": var.rc_lookahead,
            "aq_strength": var.aq_strength,
            "multipass": var.multipass,
            "b_ref_mode": var.b_ref_mode if var.codec == "hevc" else "disabled",
            "main10": int(var.main10 if var.codec == "hevc" else False),
            "elapsed_s": round(enc_elapsed, 3),
            "duration_s": round(duration_s, 3),
            "rtf": round((duration_s / enc_elapsed) if enc_elapsed > 0 else 0.0, 3),
            "size_in": size_in,
            "size_out": size_out,
            "size_reduction_percent": round(size_red, 3),
            "efficiency_ratio": round(eff_ratio, 3),
            "status": "ok",
            "note": note,
        }
        row.update({k: round(float(v), 6) for k, v in metrics.items()})
        state.rows.append(row)
        metric_tag = (
            f"vmaf {metrics.get('vmaf', 0.0):.1f}"
            if "vmaf" in metrics
            else (
                f"ssim {metrics.get('ssim', 0.0):.4f}"
                if "ssim" in metrics
                else "metric N/A"
            )
        )
        typer.echo(
            f"<- Done:  {inp.name} | {var.codec} cq{var.quality} | rtf {row['rtf']:.2f} | sizeΔ {row['size_reduction_percent']:.1f}% | {metric_tag} | {enc_elapsed:.1f}s"
        )

        # Cleanup
        if not state.keep_outputs:
            with contextlib.suppress(Exception):
                out_file.unlink()
        state.processed_count += 1
        slug = _variant_slug(var)
        state.variant_pending[slug] -= 1
        if state.variant_pending[slug] == 0:
            typer.echo(f"<= Variant done:  {slug}")


# * Utilities --------------------------------------------------------------------
def _list_media_files(directory: Path, exts: Iterable[str]) -> list[Path]:
    return [
        p
        for p in sorted(directory.iterdir())
        if p.is_file() and p.suffix.lower() in exts
    ]


def _variant_slug(v: VariantParams) -> str:
    base = f"{v.codec}_cq{v.quality}_bf{v.b_frames}_aq{int(v.temporal_aq)}_aqs{v.aq_strength}_la{v.rc_lookahead}_mp{v.multipass}"
    if v.codec == "hevc":
        base += f"_br{v.b_ref_mode}"
        if v.main10:
            base += "_main10"
    return base


def _variant_params_dict(v: VariantParams) -> dict[str, Any]:
    return {
        "codec": v.codec,
        "quality": v.quality,
        "b_frames": v.b_frames,
        "temporal_aq": int(v.temporal_aq),
        "rc_lookahead": v.rc_lookahead,
        "aq_strength": v.aq_strength,
        "multipass": v.multipass,
        "b_ref_mode": v.b_ref_mode if v.codec == "hevc" else "disabled",
        "main10": int(v.main10 if v.codec == "hevc" else False),
    }


def _variants_full_h264_for_cq(q: str) -> list[VariantParams]:
    """Build full-profile H.264 variants for a given CQ."""
    items: list[VariantParams] = []
    for bf in (2, 3):
        for taq in (True, False):
            for la in (16, 32, 48, 64):
                for aqs in (6, 8, 10, 12):
                    for mp in ("off", "fullres"):
                        mp_val: Literal["off", "fullres"] = (
                            "off" if mp == "off" else "fullres"
                        )
                        items.append(
                            VariantParams(
                                codec="h264",
                                quality=q,
                                b_frames=bf,
                                temporal_aq=taq,
                                rc_lookahead=la,
                                aq_strength=aqs,
                                multipass=mp_val,
                                b_ref_mode="disabled",
                                main10=False,
                                label=f"full-h264-cq{q}-bf{bf}-taq{int(taq)}-la{la}-aqs{aqs}-mp{mp}",
                            )
                        )
    return items


def _variants_full_hevc_for_cq(q: str) -> list[VariantParams]:
    """Build full-profile HEVC variants for a given CQ."""
    items: list[VariantParams] = []
    for bf in (3, 4, 5):
        for bref in ("disabled", "middle"):
            for taq in (True, False):
                for la in (16, 32, 48, 64):
                    for aqs in (6, 8, 10, 12):
                        for mp in ("off", "fullres"):
                            mp_val: Literal["off", "fullres"] = (
                                "off" if mp == "off" else "fullres"
                            )
                            for m10 in (False, True):
                                items.append(
                                    VariantParams(
                                        codec="hevc",
                                        quality=q,
                                        b_frames=bf,
                                        temporal_aq=taq,
                                        rc_lookahead=la,
                                        aq_strength=aqs,
                                        multipass=mp_val,
                                        b_ref_mode=bref,
                                        main10=m10,
                                        label=f"full-hevc{'-10bit' if m10 else ''}-cq{q}-bf{bf}-br{bref}-taq{int(taq)}-la{la}-aqs{aqs}-mp{mp}",
                                    )
                                )
    return items


def generate_variants(
    profile: Literal["full", "extended", "quick", "custom"],
    max_variants: int | None = None,
) -> list[VariantParams]:
    """
    Generate a parameter grid for the chosen profile.
    Filters to `max_variants` earliest items if provided.
    """
    variants: list[VariantParams] = []
    if profile in ("quick", "custom"):
        # * Small, fast grid
        for codec in ("h264", "hevc"):
            qualities = ["26", "34"]
            for q in qualities:
                if codec == "h264":
                    variants.append(
                        VariantParams(
                            codec="h264",
                            quality=q,
                            b_frames=2,
                            temporal_aq=True,
                            rc_lookahead=32,
                            aq_strength=8,
                            multipass="off",
                            b_ref_mode="disabled",
                            main10=False,
                            label=f"quick-{codec}-cq{q}",
                        )
                    )
                else:
                    for m10 in (False,):
                        variants.append(
                            VariantParams(
                                codec="hevc",
                                quality=q,
                                b_frames=4,
                                temporal_aq=True,
                                rc_lookahead=32,
                                aq_strength=8,
                                multipass="off",
                                b_ref_mode="middle",
                                main10=m10,
                                label=f"quick-{codec}{'-10bit' if m10 else ''}-cq{q}",
                            )
                        )
    else:
        # * Full/extended grid (extended currently aliased to full)
        qualities = ["26", "30", "34", "40"]
        for q in qualities:
            variants.extend(_variants_full_h264_for_cq(q))
            variants.extend(_variants_full_hevc_for_cq(q))
        # * Add two curated presets: fastest and worst-quality (for analysis anchors)
        variants.insert(
            0,
            VariantParams(
                codec="h264",
                quality="40",
                b_frames=0,
                temporal_aq=False,
                rc_lookahead=0,
                aq_strength=0,
                multipass="off",
                b_ref_mode="disabled",
                main10=False,
                label="anchor-fastest",
            ),
        )
        variants.append(
            VariantParams(
                codec="hevc",
                quality="40",
                b_frames=0,
                temporal_aq=False,
                rc_lookahead=0,
                aq_strength=0,
                multipass="off",
                b_ref_mode="disabled",
                main10=True,
                label="anchor-worst-quality",
            )
        )
    if isinstance(max_variants, int) and max_variants >= 0:
        return variants[:max_variants]
    return variants


def detect_libvmaf() -> bool:
    """Detect if FFmpeg has libvmaf filter."""
    try:
        res = subprocess.run(
            ["ffmpeg", "-hide_banner", "-filters"],
            capture_output=True,
            text=True,
        )
        if res.returncode != 0:
            return False
        txt = (res.stdout or "") + (res.stderr or "")
        return "libvmaf" in txt
    except Exception:
        return False


def choose_metric_backend(
    has_vmaf: bool, require_vmaf: bool
) -> Literal["vmaf", "fallback"]:
    """
    Decide metric backend based on availability and requirement.
    Returns 'vmaf' or 'fallback'. Raises if require_vmaf is True and not available.
    """
    if has_vmaf:
        return "vmaf"
    if require_vmaf:
        raise RuntimeError("VMAF is required but not available.")
    return "fallback"


def _vmaf_model_paths(model_dir: Path | None) -> tuple[str | None, str | None]:
    """Return (vmaf_model, vmaf_neg_model) paths if discoverable, else (None, None)."""
    if not model_dir:
        return (None, None)
    try:
        vmaf = None
        vmaf_neg = None
        candidates = [
            "vmaf_v0.6.1.json",
            "vmaf_4k_v0.6.1.json",
            "vmaf_v0.6.1neg.json",
            "vmaf_4k_v0.6.1neg.json",
        ]
        for c in candidates:
            p = model_dir / c
            if p.exists():
                if "neg" in c:
                    vmaf_neg = str(p)
                else:
                    vmaf = str(p)
        return (vmaf, vmaf_neg)
    except Exception:
        return (None, None)


async def _encode_once(
    src: Path,
    out_dir: Path,
    variant: VariantParams,
    overwrite: bool,
    *,
    stats: Optional[ProcessingStats] = None,
    total_duration: Optional[float] = None,
    require_nvenc: bool = True,
) -> tuple[Path | None, bool, float]:
    """
    Encode a single input with provided parameters.

    Returns:
        (output_path, used_nvenc, elapsed_s)
    """
    ensure_dir_exists(out_dir)
    # * Build output file path in Windows temp root to avoid clutter
    ensure_dir_exists(WIN_TEMP_ROOT)
    out_name = f"{src.stem}__{_variant_slug(variant)}.mkv"
    temp_out = WIN_TEMP_ROOT / out_name
    if temp_out.exists() and overwrite:
        with contextlib.suppress(Exception):
            temp_out.unlink()

    # * Base NVENC options (or software fallback)
    base = get_nvenc_video_options(variant.codec, variant.quality)
    using_nvenc = any(x in base for x in ("h264_nvenc", "hevc_nvenc"))
    if require_nvenc and not using_nvenc:
        raise RuntimeError(
            f"NVENC encoder not available for codec '{variant.codec}'. Install FFmpeg with NVENC support."
        )

    # * Apply overrides only if NVENC is actually used
    extra: list[str] = []
    if using_nvenc:
        extra.extend(["-bf", str(variant.b_frames)])
        # Clamp rc-lookahead to a safe range [0..64]
        rc_la = max(0, min(64, int(variant.rc_lookahead)))
        extra.extend(["-rc-lookahead", str(rc_la)])
        # Clamp aq-strength to NVENC-supported range [1..15]
        aq_val = max(1, min(15, int(variant.aq_strength)))
        extra.extend(["-aq-strength", str(aq_val)])
        extra.extend(["-temporal_aq", "1" if variant.temporal_aq else "0"])
        if variant.codec == "hevc":
            extra.extend(["-b_ref_mode", variant.b_ref_mode])
            if variant.main10:
                extra.extend(["-pix_fmt", "p010le", "-profile:v", "main10"])
        if variant.multipass != "off":
            extra.extend(
                ["-multipass", "fullres" if variant.multipass == "fullres" else "qres"]
            )
    else:
        # * Software fallback (libx264/libx265) — apply limited safe flags
        extra.extend(["-bf", str(variant.b_frames)])
        if variant.codec == "hevc" and variant.main10:
            extra.extend(["-pix_fmt", "yuv420p10le"])

    # * Compose command
    cmd: list[str] = (
        [
            "ffmpeg",
            "-hide_banner",
            "-y" if overwrite else "-n",
            "-i",
            str(src),
            "-an",  # drop audio to keep comparisons video-only and faster
        ]
        + base
        + extra
        + [str(temp_out)]
    )

    t0 = time.perf_counter()
    ok = await run_ffmpeg_command(
        cmd,
        stats=stats,
        quiet=True,
        output_path=str(temp_out),
        filename=src.name,
        total_duration=total_duration,
    )
    elapsed = max(0.0, time.perf_counter() - t0)
    if not ok or not temp_out.exists():
        return (None, using_nvenc, elapsed)
    return (temp_out, using_nvenc, elapsed)


async def compute_metrics_vmaf(
    reference: Path,
    distorted: Path,
    *,
    model_dir: Path | None,
) -> dict[str, float]:
    """
    Compute VMAF and VMAF NEG using libvmaf, if possible.
    Returns dict with keys: vmaf, vmaf_neg (missing keys if not computed).
    """
    results: dict[str, float] = {}
    vmaf_model, vmaf_neg_model = _vmaf_model_paths(model_dir)

    # * Build safe temp path for VMAF logs (relative folder to avoid drive letter issues)
    tmp_dir = Path(".nvbench") / "tmp"
    ensure_dir_exists(tmp_dir)

    def _safe_stem(p: Path) -> str:
        # replace unsuitable chars with underscores (keep alnum, dash, underscore, dot)
        return re.sub(r"[^A-Za-z0-9._-]+", "_", p.stem)

    def _escape_for_filter_path(p: Path) -> str:
        # Use forward slashes and escape colon/spaces for ffmpeg filter arg
        s = p.as_posix()
        s = s.replace(":", r"\:")
        s = s.replace(" ", r"\ ")
        return s

    async def _run_one(model_path: str | None, tag: str) -> float | None:
        safe_name = _safe_stem(distorted) + ".vmaf.json"
        log_json = tmp_dir / safe_name
        if log_json.exists():
            with contextlib.suppress(Exception):
                log_json.unlink()
        args = [
            "ffmpeg",
            "-hide_banner",
            "-i",
            str(reference),
            "-i",
            str(distorted),
            "-lavfi",
            f"[0:v][1:v]libvmaf=log_fmt=json:log_path={_escape_for_filter_path(log_json)}:n_threads=4"
            + (
                f":model_path={_escape_for_filter_path(Path(model_path))}"
                if model_path
                else ""
            ),
            "-f",
            "null",
            "-",
        ]
        typer.echo(f"[METRICS] Starting {tag} for {distorted.name}")
        ok = await run_ffmpeg_command(args, quiet=True, filename=distorted.name)
        if not ok or not log_json.exists():
            typer.echo(f"[METRICS] {tag} failed for {distorted.name}")
            return None
        try:
            data = json.loads(log_json.read_text(encoding="utf-8"))
            # libvmaf JSON schema: extract mean score
            score = float(
                data.get("pooled_metrics", {}).get("vmaf", {}).get("mean", 0.0)
            )
            typer.echo(f"[METRICS] {tag} done: {score:.2f}")
            return score
        except Exception:
            return None
        finally:
            with contextlib.suppress(Exception):
                log_json.unlink()

    # * Standard VMAF
    vmaf_val = await _run_one(vmaf_model, "VMAF")
    if vmaf_val is not None:
        results["vmaf"] = vmaf_val
    # * VMAF NEG
    vmaf_neg_val = await _run_one(vmaf_neg_model, "VMAF_NEG")
    if vmaf_neg_val is not None:
        results["vmaf_neg"] = vmaf_neg_val
    return results


async def compute_metrics_ssim_psnr(
    reference: Path, distorted: Path
) -> dict[str, float]:
    """
    Compute SSIM/PSNR as fallback when VMAF is unavailable.
    Returns keys: ssim, psnr (if parseable).
    """
    # ssim and psnr can be computed together via filter_complex with tee syntax,
    # but parsing stdout is simpler if done in two passes to keep regex stable.
    out: dict[str, float] = {}

    async def _run_ssim() -> float | None:
        typer.echo(f"[METRICS] Starting SSIM for {distorted.name}")
        args = [
            "ffmpeg",
            "-hide_banner",
            "-i",
            str(reference),
            "-i",
            str(distorted),
            "-lavfi",
            "ssim",
            "-f",
            "null",
            "-",
        ]
        # We do not get stdout from run_ffmpeg_command; run a raw subprocess for parsing in this limited case.
        try:
            proc = await asyncio.create_subprocess_exec(
                *args, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.STDOUT
            )
            assert proc.stdout is not None
            buf = await proc.stdout.read()
            await proc.wait()
            txt = buf.decode("utf-8", errors="replace")
            # Example: "SSIM Y:0.993930 U:0.997548 V:0.997405 All:0.995236 (21.971812)"
            m = re.search(r"SSIM.*All:(\d+\.\d+)", txt)
            if m:
                typer.echo(f"[METRICS] SSIM done: {float(m.group(1)):.4f}")
                return float(m.group(1))
        except Exception:
            return None
        return None

    async def _run_psnr() -> float | None:
        typer.echo(f"[METRICS] Starting PSNR for {distorted.name}")
        args = [
            "ffmpeg",
            "-hide_banner",
            "-i",
            str(reference),
            "-i",
            str(distorted),
            "-lavfi",
            "psnr",
            "-f",
            "null",
            "-",
        ]
        try:
            proc = await asyncio.create_subprocess_exec(
                *args, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.STDOUT
            )
            assert proc.stdout is not None
            buf = await proc.stdout.read()
            await proc.wait()
            txt = buf.decode("utf-8", errors="replace")
            # Example: "average:29.64 min:22.79 max:34.19"
            m = re.search(r"average:(\d+\.\d+)", txt)
            if m:
                typer.echo(f"[METRICS] PSNR done: {float(m.group(1)):.2f}")
                return float(m.group(1))
        except Exception:
            return None
        return None

    ssim_val, psnr_val = await asyncio.gather(_run_ssim(), _run_psnr())
    if ssim_val is not None:
        out["ssim"] = ssim_val
    if psnr_val is not None:
        out["psnr"] = psnr_val
    return out


def _efficiency_metric(
    size_in: int, size_out: int, quality_score: float | None
) -> tuple[float, float]:
    """
    Compute size reduction percent and efficiency ratio vs quality loss.

    Returns:
        (size_reduction_percent, efficiency_ratio)
    """
    if size_in <= 0 or size_out < 0:
        return (0.0, 0.0)
    size_red = (1.0 - (float(size_out) / float(size_in))) * 100.0
    if quality_score is None:
        return (size_red, 0.0)
    # * Interpret quality_score ~= VMAF (0..100); loss = max(0, 100 - score)
    loss = max(0.0, 100.0 - float(quality_score))
    ratio = (size_red / max(1e-6, loss)) if loss > 0.0 else float("inf")
    # Avoid inf in reports
    if math.isinf(ratio) or ratio > 1e6:
        ratio = 1e6
    return (size_red, ratio)


def _aggregate_by_variant(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    buckets: dict[str, list[dict[str, Any]]] = {}
    for r in rows:
        key = str(r.get("variant", ""))
        buckets.setdefault(key, []).append(r)
    agg: list[dict[str, Any]] = []
    for k, items in buckets.items():

        def _avg(key: str) -> float:
            vals: list[float] = []
            for it in items:
                v = it.get(key)
                try:
                    if isinstance(v, (int, float)):
                        vals.append(float(v))
                except Exception:
                    pass
            return (sum(vals) / float(len(vals))) if vals else 0.0

        # Take parameter columns from the first item in the group (all share the same variant)
        first = items[0] if items else {}
        # Aggregate input names (for MD display)
        input_names = sorted(
            {
                Path(str(it.get("input", ""))).name
                for it in items
                if str(it.get("input", ""))
            }
        )
        input_name = input_names[0] if len(input_names) == 1 else "(multiple)"
        agg.append(
            {
                "variant": k,
                "input_name": input_name,
                "codec": first.get("codec", ""),
                "quality": first.get("quality", ""),
                "b_frames": first.get("b_frames", ""),
                "temporal_aq": first.get("temporal_aq", ""),
                "rc_lookahead": first.get("rc_lookahead", ""),
                "aq_strength": first.get("aq_strength", ""),
                "multipass": first.get("multipass", ""),
                "b_ref_mode": first.get("b_ref_mode", ""),
                "main10": first.get("main10", ""),
                "count": len(items),
                "avg_elapsed_s": round(_avg("elapsed_s"), 3),
                "avg_duration_s": round(_avg("duration_s"), 3),
                "avg_rtf": round(_avg("rtf"), 3),
                "avg_size_reduction_percent": round(_avg("size_reduction_percent"), 3),
                "avg_vmaf": round(_avg("vmaf"), 3),
                "avg_vmaf_neg": round(_avg("vmaf_neg"), 3),
                "avg_ssim": round(_avg("ssim"), 5),
                "avg_psnr": round(_avg("psnr"), 3),
                "avg_efficiency_ratio": round(_avg("efficiency_ratio"), 3),
                "notes": ";".join(
                    sorted({str(it.get("note", "")) for it in items if it.get("note")})
                ),
            }
        )
    return sorted(agg, key=lambda r: r["variant"])


def write_reports(per_file_rows: list[dict[str, Any]], out_dir: Path) -> None:
    """Write CSV/JSON/Markdown reports for per-file and aggregated stats."""
    ensure_dir_exists(out_dir)
    agg_rows = _aggregate_by_variant(per_file_rows)
    # Per-file
    per_file_csv = out_dir / "nvenc_benchmark_per_file.csv"
    per_file_json = out_dir / "nvenc_benchmark_per_file.json"
    per_file_md = out_dir / "nvenc_benchmark_per_file.md"
    # Aggregated
    agg_csv = out_dir / "nvenc_benchmark_agg.csv"
    agg_json = out_dir / "nvenc_benchmark_agg.json"
    agg_md = out_dir / "nvenc_benchmark_agg.md"

    if per_file_rows:
        base_order = [
            "variant",
            "label",
            "input",
            "codec",
            "quality",
            "b_frames",
            "temporal_aq",
            "rc_lookahead",
            "aq_strength",
            "multipass",
            "b_ref_mode",
            "main10",
            "elapsed_s",
            "duration_s",
            "rtf",
            "size_in",
            "size_out",
            "size_reduction_percent",
            "efficiency_ratio",
            "vmaf",
            "vmaf_neg",
            "ssim",
            "psnr",
            "status",
            "note",
        ]
        fields = [f for f in base_order if any(f in r for r in per_file_rows)]
        with per_file_csv.open("w", newline="", encoding="utf-8") as f:
            w = csv.DictWriter(f, fieldnames=fields)
            w.writeheader()
            w.writerows(per_file_rows)
        per_file_json.write_text(
            json.dumps(per_file_rows, ensure_ascii=False, indent=2), encoding="utf-8"
        )

        lines = [
            "# NVENC Benchmark (Per-file)",
            "",
            "Variant | Label | Input | Codec | CQ | BF | TAQ | LA | AQS | MP | BREF | 10bit | RTF | VMAF | VMAF_NEG | SSIM | PSNR | SizeRed% | EffRatio | Note",
            "---|---|---|---|---:|---:|---:|---:|---:|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---",
        ]
        for r in per_file_rows:
            lines.append(
                f"{r.get('variant','')} | {r.get('label','')} | {Path(str(r.get('input',''))).name} | {r.get('codec','')} | {r.get('quality','')} | "
                f"{r.get('b_frames','')} | {r.get('temporal_aq','')} | {r.get('rc_lookahead','')} | {r.get('aq_strength','')} | {r.get('multipass','')} | {r.get('b_ref_mode','')} | {r.get('main10','')} | "
                f"{r.get('rtf',0.0)} | {r.get('vmaf','')} | {r.get('vmaf_neg','')} | {r.get('ssim','')} | {r.get('psnr','')} | "
                f"{r.get('size_reduction_percent','')} | {r.get('efficiency_ratio','')} | {r.get('note','')}"
            )
        per_file_md.write_text("\n".join(lines), encoding="utf-8")

    if agg_rows:
        base_order = [
            "variant",
            "input_name",
            "codec",
            "quality",
            "b_frames",
            "temporal_aq",
            "rc_lookahead",
            "aq_strength",
            "multipass",
            "b_ref_mode",
            "main10",
            "avg_elapsed_s",
            "avg_duration_s",
            "count",
            "avg_rtf",
            "avg_size_reduction_percent",
            "avg_vmaf",
            "avg_vmaf_neg",
            "avg_ssim",
            "avg_psnr",
            "avg_efficiency_ratio",
            "notes",
        ]
        fields = [f for f in base_order if any(f in r for r in agg_rows)]
        with agg_csv.open("w", newline="", encoding="utf-8") as f:
            w = csv.DictWriter(f, fieldnames=fields)
            w.writeheader()
            w.writerows(agg_rows)
        agg_json.write_text(
            json.dumps(agg_rows, ensure_ascii=False, indent=2), encoding="utf-8"
        )

        lines = [
            "# NVENC Benchmark (Aggregated)",
            "",
            "File | Codec | CQ | BF | TAQ | LA | AQS | MP | BREF | 10bit | N | Avg RTF | Avg SizeRed% | Avg VMAF | Avg VMAF_NEG | Avg SSIM | Avg PSNR | Avg EffRatio | Notes",
            "---|---|---:|---:|---:|---:|---:|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---",
        ]
        for r in agg_rows:
            lines.append(
                f"{r.get('input_name','')} | {r.get('codec','')} | {r.get('quality','')} | {r.get('b_frames','')} | {r.get('temporal_aq','')} | {r.get('rc_lookahead','')} | {r.get('aq_strength','')} | {r.get('multipass','')} | {r.get('b_ref_mode','')} | {r.get('main10','')} | "
                f"{r.get('count',0)} | {r.get('avg_rtf',0.0)} | {r.get('avg_size_reduction_percent',0.0)} | {r.get('avg_vmaf',0.0)} | {r.get('avg_vmaf_neg',0.0)} | {r.get('avg_ssim',0.0)} | {r.get('avg_psnr',0.0)} | "
                f"{r.get('avg_efficiency_ratio',0.0)} | {r.get('notes','')}"
            )
        agg_md.write_text("\n".join(lines), encoding="utf-8")


async def _run_benchmark_async(
    inputs: list[Path],
    out_reports: Path,
    profile: Literal["full", "extended", "quick", "custom"],
    *,
    max_variants: int,
    require_vmaf: bool,
    vmaf_model_dir: Path | None,
    overwrite: bool,
    concurrency: int,
    keep_outputs: bool,
    require_nvenc: bool,
    cq_only: Optional[str],
    allow_h264: bool,
    allow_hevc: bool,
) -> None:
    stats = ProcessingStats()
    ensure_dir_exists(out_reports)
    # Prepare temp root
    ensure_dir_exists(WIN_TEMP_ROOT)
    # Enumerate variants
    # * Generate full grid first to allow correct CQ filtering before limiting
    variants = generate_variants(profile, max_variants=None)
    if cq_only:
        variants = [v for v in variants if v.quality == cq_only]
    # * Filter by codec flags
    variants = [
        v
        for v in variants
        if ((v.codec == "h264" and allow_h264) or (v.codec == "hevc" and allow_hevc))
    ]
    if isinstance(max_variants, int) and max_variants >= 0:
        variants = variants[:max_variants]
    typer.echo(
        f"Variants planned: {len(variants)} | inputs={len(inputs)} | profile={profile}"
    )
    # Detect VMAF availability once
    has_vmaf = detect_libvmaf()
    if not has_vmaf and require_vmaf:
        raise RuntimeError(
            "libvmaf is not available in this FFmpeg build (use --require-vmaf only with VMAF-enabled FFmpeg)."
        )

    sem = asyncio.Semaphore(max(1, concurrency))
    rows: list[dict[str, Any]] = []
    total_tasks = len(variants) * len(inputs)
    processed_count = 0
    start_ts = time.perf_counter()
    stop_event = asyncio.Event()
    # Track per-variant pending counts for persisted start/done messages
    variant_pending: dict[str, int] = {}
    # * Live status tracking state
    current_variant_slug: Optional[str] = None
    current_variant_cfg: str = ""
    current_file_start_ts: float | None = None
    variant_start_ts: dict[str, float] = {}
    variant_file_elapsed_sum: dict[str, float] = {}
    variant_processed_count: dict[str, int] = {}
    for v in variants:
        slug = _variant_slug(v)
        variant_pending[slug] = len(inputs)
        typer.echo(f"=> Variant start: {slug} | {v.label}")

    async def _heartbeat() -> None:
        last_len = 0
        while not stop_event.is_set():
            try:
                elapsed = max(0.0, time.perf_counter() - start_ts)
                done = processed_count
                total = total_tasks
                # * Benchmark ETA
                if done > 0:
                    avg = elapsed / float(done)
                    eta = avg * max(0, total - done)
                else:
                    eta = 0.0
                # * Variants progress
                var_done = sum(1 for k, v in variant_pending.items() if v == 0)
                var_total = len(variant_pending)
                # * EPF, EPV, ETAv
                epf = (
                    (time.perf_counter() - current_file_start_ts)
                    if current_file_start_ts
                    else 0.0
                )
                epv = 0.0
                etav = 0.0
                if current_variant_slug:
                    vslug = current_variant_slug
                    vstart = variant_start_ts.get(vslug, start_ts)
                    epv = max(0.0, time.perf_counter() - vstart)
                    v_done_files = variant_processed_count.get(vslug, 0)
                    v_total_files = len(inputs)
                    v_elapsed_sum = variant_file_elapsed_sum.get(vslug, 0.0)
                    v_avg = (v_elapsed_sum / v_done_files) if v_done_files > 0 else 0.0
                    v_rem = max(0, v_total_files - v_done_files)
                    etav = v_avg * v_rem
                else:
                    v_done_files = 0
                    v_total_files = len(inputs)
                # * Live status line
                line = (
                    f" files {v_done_files}/{v_total_files} | vars {var_done}/{var_total} | {current_variant_cfg}"
                    f" | EPF {epf:.1f}s | EPV {epv:.1f}s | EPB {elapsed:.1f}s | ETAv {format_duration(etav)} | ETA {format_duration(eta)}"
                )
                padded = line
                if len(padded) < last_len:
                    padded = padded + (" " * (last_len - len(padded)))
                sys.stdout.write("\r" + padded)
                sys.stdout.flush()
                last_len = max(last_len, len(line))
            except Exception:
                pass
            await asyncio.sleep(0.5)
        # Clear line
        try:
            sys.stdout.write("\r" + " " * last_len + "\r")
            sys.stdout.flush()
        except Exception:
            pass

    async def _process_one(inp: Path, var: VariantParams) -> None:
        nonlocal processed_count, current_variant_slug, current_variant_cfg, current_file_start_ts
        async with sem:
            # Duration for RTF
            dur = await get_video_duration(str(inp))
            duration_s = float(dur) if dur is not None else 0.0
            # Input size
            try:
                size_in = inp.stat().st_size
            except Exception:
                size_in = 0
            # Start line (persisted)
            typer.echo(
                f"-> Start: {inp.name} | {var.codec} cq{var.quality} bf{var.b_frames} taq{int(var.temporal_aq)} la{var.rc_lookahead} aqs{var.aq_strength} mp{var.multipass}{' main10' if (var.codec=='hevc' and var.main10) else ''}"
            )
            # * Live status: mark current variant/file
            vslug = _variant_slug(var)
            if vslug not in variant_start_ts:
                variant_start_ts[vslug] = time.perf_counter()
                variant_file_elapsed_sum[vslug] = 0.0
                variant_processed_count[vslug] = 0
            current_variant_slug = vslug
            current_variant_cfg = f"{var.codec} cq{var.quality} bf{var.b_frames} br{var.b_ref_mode if var.codec=='hevc' else 'disabled'} taq{int(var.temporal_aq)} la{var.rc_lookahead} aqs{var.aq_strength} mp{var.multipass}{' 10bit' if (var.codec=='hevc' and var.main10) else ''}"
            current_file_start_ts = time.perf_counter()
            # Encode (per-file progress rendered by run_ffmpeg_command when total_duration is provided)
            out_file, used_nvenc, enc_elapsed = await _encode_once(
                inp,
                WIN_TEMP_ROOT,
                var,
                overwrite=overwrite,
                stats=stats,
                total_duration=duration_s if duration_s > 0 else None,
                require_nvenc=require_nvenc,
            )
            # * Update per-variant accumulators
            try:
                variant_file_elapsed_sum[vslug] = (
                    variant_file_elapsed_sum.get(vslug, 0.0) + enc_elapsed
                )
                variant_processed_count[vslug] = (
                    variant_processed_count.get(vslug, 0) + 1
                )
            except Exception:
                pass
            note = ""
            if not used_nvenc:
                note = "software_fallback"
            if out_file is None or not out_file.exists():
                # Failed encode
                rows.append(
                    {
                        "input": str(inp),
                        "variant": _variant_slug(var),
                        "label": var.label,
                        "codec": var.codec,
                        "quality": var.quality,
                        "elapsed_s": round(enc_elapsed, 3),
                        "duration_s": round(duration_s, 3),
                        "rtf": round(
                            (duration_s / enc_elapsed) if enc_elapsed > 0 else 0.0, 3
                        ),
                        "size_in": size_in,
                        "size_out": 0,
                        "size_reduction_percent": 0.0,
                        "efficiency_ratio": 0.0,
                        "status": "failed",
                        "note": note,
                    }
                )
                typer.echo(
                    f"<- Fail:  {inp.name} | {var.codec} cq{var.quality} | elapsed {enc_elapsed:.1f}s"
                )
                processed_count += 1
                # Decrement variant pending and emit done if zero
                slug = _variant_slug(var)
                variant_pending[slug] -= 1
                if variant_pending[slug] == 0:
                    typer.echo(f"<= Variant done:  {slug}")
                return

            # Output size
            try:
                size_out = out_file.stat().st_size
            except Exception:
                size_out = 0

            # Metrics
            metrics: dict[str, float] = {}
            if has_vmaf:
                metrics = await compute_metrics_vmaf(
                    inp, out_file, model_dir=vmaf_model_dir
                )
                if require_vmaf and ("vmaf" not in metrics):
                    rows.append(
                        {
                            "input": str(inp),
                            "variant": _variant_slug(var),
                            "label": var.label,
                            "codec": var.codec,
                            "quality": var.quality,
                            "elapsed_s": round(enc_elapsed, 3),
                            "duration_s": round(duration_s, 3),
                            "rtf": round(
                                (duration_s / enc_elapsed) if enc_elapsed > 0 else 0.0,
                                3,
                            ),
                            "size_in": size_in,
                            "size_out": size_out,
                            "size_reduction_percent": 0.0,
                            "efficiency_ratio": 0.0,
                            "status": "failed-metric",
                            "note": "vmaf-required",
                        }
                    )
                    if not keep_outputs:
                        with contextlib.suppress(Exception):
                            out_file.unlink()
                    return
            if not metrics:
                metrics = await compute_metrics_ssim_psnr(inp, out_file)

            qual_for_eff = metrics.get("vmaf")
            size_red, eff_ratio = _efficiency_metric(size_in, size_out, qual_for_eff)
            row: dict[str, Any] = {
                "input": str(inp),
                "variant": _variant_slug(var),
                "label": var.label,
                "codec": var.codec,
                "quality": var.quality,
                "b_frames": var.b_frames,
                "temporal_aq": int(var.temporal_aq),
                "rc_lookahead": var.rc_lookahead,
                "aq_strength": var.aq_strength,
                "multipass": var.multipass,
                "b_ref_mode": var.b_ref_mode if var.codec == "hevc" else "disabled",
                "main10": int(var.main10 if var.codec == "hevc" else False),
                "elapsed_s": round(enc_elapsed, 3),
                "duration_s": round(duration_s, 3),
                "rtf": round((duration_s / enc_elapsed) if enc_elapsed > 0 else 0.0, 3),
                "size_in": size_in,
                "size_out": size_out,
                "size_reduction_percent": round(size_red, 3),
                "efficiency_ratio": round(eff_ratio, 3),
                "status": "ok",
                "note": note,
            }
            # Merge metrics
            row.update({k: round(float(v), 6) for k, v in metrics.items()})
            rows.append(row)
            # Done line (persisted)
            metric_tag = (
                f"vmaf {metrics.get('vmaf', 0.0):.1f}"
                if "vmaf" in metrics
                else (
                    f"ssim {metrics.get('ssim', 0.0):.4f}"
                    if "ssim" in metrics
                    else "metric N/A"
                )
            )
            typer.echo(
                f"<- Done:  {inp.name} | {var.codec} cq{var.quality} | rtf {row['rtf']:.2f} | sizeΔ {row['size_reduction_percent']:.1f}% | {metric_tag} | {enc_elapsed:.1f}s"
            )

            # Cleanup
            if not keep_outputs:
                with contextlib.suppress(Exception):
                    out_file.unlink()
            processed_count += 1
            # Decrement variant pending and emit done if zero
            slug = _variant_slug(var)
            variant_pending[slug] -= 1
            if variant_pending[slug] == 0:
                typer.echo(f"<= Variant done:  {slug}")

    # Process all tasks
    tasks: list[asyncio.Task[Any]] = []
    for v in variants:
        for inp in inputs:
            tasks.append(asyncio.create_task(_process_one(inp, v)))
    # Progress task
    progress_task = asyncio.create_task(_heartbeat())
    try:
        await asyncio.gather(*tasks)
    except asyncio.CancelledError:
        # Cancel all tasks gracefully
        for t in tasks:
            if not t.done():
                t.cancel()
        with contextlib.suppress(Exception):
            await asyncio.gather(*tasks, return_exceptions=True)
    finally:
        # Stop heartbeat
        if not stop_event.is_set():
            stop_event.set()
        with contextlib.suppress(Exception):
            await progress_task
        # Ensure temp does not grow unbounded
        if not keep_outputs:
            try:
                for p in WIN_TEMP_ROOT.glob("*"):
                    with contextlib.suppress(Exception):
                        if p.is_file():
                            p.unlink()
            except Exception:
                pass
    # Write reports
    write_reports(rows, out_reports)
    # Print console summary
    print_separator()
    typer.echo(
        f"NVENC benchmark complete | inputs={len(inputs)} | variants={len(variants)} | out={out_reports}"
    )
    print_separator()


def _collect_inputs(inputs: list[Path], input_dir: Path | None) -> list[Path]:
    files: list[Path] = []
    files.extend([p for p in inputs if p.exists() and p.is_file()])
    if input_dir and input_dir.exists() and input_dir.is_dir():
        files.extend(_list_media_files(input_dir, DEFAULT_EXTS))
    # Unique + sort
    uniq = sorted({p.resolve() for p in files})
    return uniq


@app.command("run")
def run_benchmark(
    input: list[Path] = typer.Option(
        [], "--input", "-i", help="Input video file(s). Specify multiple times."
    ),
    input_dir: Path | None = typer.Option(
        None, "--input-dir", help="Directory with input videos."
    ),
    out: Path = typer.Option(
        DEFAULT_REPORTS_DIR, "--out", help="Directory to write NVENC benchmark reports"
    ),
    profile: Literal["full", "extended", "quick", "custom"] = typer.Option(
        "full", "--profile", case_sensitive=False
    ),
    max_variants: int = typer.Option(
        200, "--max-variants", help="Limit number of parameter variants (-1 for all)"
    ),
    require_vmaf: bool = typer.Option(
        False, "--require-vmaf", help="Fail instead of falling back to SSIM/PSNR"
    ),
    vmaf_model_dir: Path | None = typer.Option(
        None, "--vmaf-model-dir", help="Directory containing VMAF model json files"
    ),
    overwrite: bool = typer.Option(
        True, "--overwrite/--no-overwrite", help="Overwrite intermediate files"
    ),
    concurrency: int = typer.Option(
        1,
        "--concurrency",
        min=1,
        help="Concurrent encodes (default 1 to avoid GPU contention)",
    ),
    keep_outputs: bool = typer.Option(
        False, "--keep-outputs", help="Keep encoded files under T:\\Temp\\NVENC"
    ),
    require_nvenc: bool = typer.Option(
        True,
        "--require-nvenc/--allow-software",
        help="Require NVENC encoder and fail on software fallback",
    ),
    cq_only: Optional[str] = typer.Option(
        None, "--cq-only", help="Only run variants with this CQ value (e.g., 30)"
    ),
    h264: bool = typer.Option(False, "--h264", help="Include H.264 variants"),
    hevc: bool = typer.Option(False, "--hevc", help="Include HEVC variants"),
) -> None:
    """Run NVENC benchmark across inputs and parameter grid."""
    files = _collect_inputs(input, input_dir)
    if not files:
        typer.secho("No input files found. Use --input or --input-dir.", err=True)
        raise typer.Exit(code=2)
    # Ensure output dir exists
    ensure_dir_exists(out)

    # Open console log file with timestamp and tee stdout
    ts = time.strftime("%Y%m%d-%H%M%S")
    log_path = out / f"nvenc_benchmark_{ts}.log"
    real_stdout = sys.stdout
    log_fh = log_path.open("w", encoding="utf-8", newline="")
    sys.stdout = _TeeStdout(real_stdout, log_fh)
    typer.echo(f"Logging console to {log_path}")

    # Execute
    # Use explicit event loop to ensure graceful cancellation and cleanup on Ctrl+C
    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        main_task = loop.create_task(
            _run_benchmark_async(
                files,
                out,
                profile,
                max_variants=max_variants,
                require_vmaf=require_vmaf,
                vmaf_model_dir=vmaf_model_dir,
                overwrite=overwrite,
                concurrency=concurrency,
                keep_outputs=keep_outputs,
                require_nvenc=require_nvenc,
                cq_only=cq_only,
                allow_h264=(h264 or (not h264 and not hevc)),
                allow_hevc=(hevc or (not h264 and not hevc)),
            )
        )
        try:
            loop.run_until_complete(main_task)
        except KeyboardInterrupt:
            typer.echo("\nInterrupted. Cancelling tasks...")
            with contextlib.suppress(Exception):
                main_task.cancel()
                loop.run_until_complete(main_task)
    finally:
        # Drain pending tasks
        pending = [t for t in asyncio.all_tasks(loop) if not t.done()]
        for t in pending:
            t.cancel()
        with contextlib.suppress(Exception):
            loop.run_until_complete(asyncio.gather(*pending, return_exceptions=True))
        with contextlib.suppress(Exception):
            loop.run_until_complete(loop.shutdown_asyncgens())
        loop.close()
        # Restore stdout and close log
        with contextlib.suppress(Exception):
            sys.stdout = real_stdout
        with contextlib.suppress(Exception):
            log_fh.flush()
            log_fh.close()
